Ces objets sont des verres, des lunettes, des b&#233;sicles, des monocles et tous les objets port&#233;s sur les yeux.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; sur les yeux &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0 g et 0,5 kg, sauf les &lt;i&gt;Lunettes de Vision &#224; 360&#176;&lt;/i&gt; qui p&#232;sent 1 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur les yeux&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-De-Perception-De-La-Mort.html&quot; title=&quot;Yeux de perception de la mort&quot;&gt;Yeux de perception de la mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perception-De-La-Mort.html&quot; title=&quot;Perception de la mort&quot;&gt;perception de la mort&lt;/a&gt;&lt;/i&gt; en permanence.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Grossissantes.html&quot; title=&quot;Lunettes grossissantes&quot;&gt;Lunettes grossissantes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-De-Lynx-(Objet).html&quot; title=&quot;Yeux de lynx&quot;&gt;Yeux de lynx&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cache-Œil-De-Pirate.html&quot; title=&quot;Cache-œil de pirate&quot;&gt;Cache-œil de pirate&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;. Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caresse-De-La-Mer.html&quot; title=&quot;Caresse de la mer&quot;&gt;caresse de la mer&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Repli-Exp&#233;ditif.html&quot; title=&quot;Repli exp&#233;ditif&quot;&gt;repli exp&#233;ditif&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;2 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;sicles-De-Compr&#233;hension.html&quot; title=&quot;B&#233;sicles de compr&#233;hension&quot;&gt;B&#233;sicles de compr&#233;hension&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Compr&#233;hension-Des-Langages.html&quot; title=&quot;Compr&#233;hension des langages&quot;&gt;compr&#233;hension des langages&lt;/a&gt;&lt;/i&gt; en permanence et un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; pour d&#233;tecter les contrefa&#231;ons et permet d’effectuer ce test sans formation.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Loupe-De-D&#233;tection.html&quot; title=&quot;Loupe de d&#233;tection&quot;&gt;Loupe de d&#233;tection&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;, et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; pour suivre des pistes.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunette-Cancani&#232;re.html&quot; title=&quot;Lunette cancani&#232;re&quot;&gt;Lunette cancani&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Compr&#233;hension-Des-Langages.html&quot; title=&quot;Compr&#233;hension des langages&quot;&gt;compr&#233;hension des langages&lt;/a&gt;&lt;/i&gt; mais uniquement pour lire sur les l&#232;vres.&lt;/td&gt;&lt;td&gt;3 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-De-Chouette.html&quot; title=&quot;Yeux de chouette&quot;&gt;Yeux de chouette&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; en permanence.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-M&#233;decin.html&quot; title=&quot;Lunettes de m&#233;decin&quot;&gt;Lunettes de m&#233;decin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets des sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Poison.html&quot; title=&quot;D&#233;tection du poison&quot;&gt;d&#233;tection du poison&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diagnostic.html&quot; title=&quot;Diagnostic&quot;&gt;diagnostic&lt;/a&gt;&lt;/i&gt; en permanence. Une fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ralentissement-Du-Poison.html&quot; title=&quot;Ralentissement du poison&quot;&gt;ralentissement du poison&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;4 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Situationnelles.html&quot; title=&quot;Lunettes situationnelles&quot;&gt;Lunettes situationnelles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt;, la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l&#39;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, ou la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18m, jusqu&#39;&#224; 10 minutes chacune, simultan&#233;ment ou non. Ne se recharge pas.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-Per&#231;ants.html&quot; title=&quot;Yeux per&#231;ants&quot;&gt;Yeux per&#231;ants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; en permanence (si le porteur poss&#232;de d&#233;j&#224; cette capacit&#233;, sa port&#233;e est doubl&#233;e).&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Du-Chasseur-De-Tr&#233;sors.html&quot; title=&quot;Lunettes du chasseur de tr&#233;sors&quot;&gt;Lunettes du chasseur de tr&#233;sors&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Des-Passages-Secrets.html&quot; title=&quot;D&#233;tection des passages secrets&quot;&gt;d&#233;tection des passages secrets&lt;/a&gt;&lt;/i&gt; (sans pr&#233;ciser comment les ouvrir) &#224; volont&#233;. Une fois par jour, permet de d&#233;tecter 100 pi&#232;ces de monnaies dans un espace r&#233;duit (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Localisation-Dobjet.html&quot; title=&quot;Localisation d&amp;#39;objet&quot;&gt;localisation d’objet&lt;/a&gt;&lt;/i&gt;). Trois fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Identification.html&quot; title=&quot;Identification&quot;&gt;identification&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;6 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monocle-Denqu&#234;teur.html&quot; title=&quot;Monocle d’enqu&#234;teur&quot;&gt;monocle d’enqu&#234;teur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;. Deux fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Zone-De-V&#233;rit&#233;.html&quot; title=&quot;Zone de v&#233;rit&#233;&quot;&gt;zone de v&#233;rit&#233;&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;6 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Vision-Jumel&#233;e.html&quot; title=&quot;Lunettes de vision jumel&#233;e&quot;&gt;Lunettes de vision jumel&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Port&#233;es par des cr&#233;atures diff&#233;rentes, chaque lentille montre au porteur de l’autre ce que son propre porteur voit.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lentilles-Du-Pr&#233;dateur.html&quot; title=&quot;Lentilles du pr&#233;dateur&quot;&gt;Lentilles du pr&#233;dateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peuvent conf&#233;rer un bonus de +1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; contre cette cr&#233;ature, ainsi qu’un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; des armes contre une cr&#233;ature qui n’est pas d&#233;j&#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html#CIBLEETUDIEE&quot; title=&quot;Le tueur&quot;&gt;cible &#233;tudi&#233;e&lt;/a&gt; du porteur, &#224; volont&#233; (un porteur qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html#CIBLEETUDIEE&quot; title=&quot;Le tueur&quot;&gt;cible &#233;tudi&#233;e&lt;/a&gt; peut &#224; la place augmenter son niveau effectif de &lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html&quot; title=&quot;Le tueur&quot;&gt;tueur&lt;/a&gt; de 5 pour en d&#233;terminer les effets).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Perce-Brume.html&quot; title=&quot;Lunettes perce-brume&quot;&gt;Lunettes perce-brume&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de voir parfaitement dans le brouillard naturel ou magique (et effets similaires). Imposent un malus de -4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Elfiques.html&quot; title=&quot;Lunettes elfiques&quot;&gt;Lunettes elfiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; pour identifier les auras et les objets magiques, et la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; en permanence (si le porteur poss&#232;de d&#233;j&#224; cette capacit&#233;, sa port&#233;e est doubl&#233;e).&lt;/td&gt;&lt;td&gt;8 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monocle-Impeccable.html&quot; title=&quot;Monocle impeccable&quot;&gt;Monocle impeccable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; o&#249; le porteur est form&#233;, aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; pour d&#233;tecter les contrefa&#231;ons et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; pour voir &#224; travers les d&#233;guisements, ainsi qu&#39;un bonus de comp&#233;tence de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; pour d&#233;voiler les illusions. R&#233;duit de moiti&#233; le temps n&#233;cessaire &#224; la fabrication d&#39;objets de ma&#238;tre.&lt;/td&gt;&lt;td&gt;8 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Lumi&#232;re-Aveuglante.html&quot; title=&quot;Lunettes de lumi&#232;re aveuglante&quot;&gt;Lunettes de lumi&#232;re aveuglante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de r&#233;sistance de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets visuels. Deux fois par jour, peuvent &#233;mettre une lumi&#232;re vive sur 9 m &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Aveugl&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;aveuglant&lt;/a&gt; les cr&#233;atures touch&#233;es.&lt;/td&gt;&lt;td&gt;8 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cache-Œil-De-Linfamie.html&quot; title=&quot;Cache-œil de l&amp;#39;infamie&quot;&gt;Cache-œil de l&#39;infamie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; pour &lt;a class=&quot;pagelink&quot; href=&quot;Acquisition-Des-Capitaux.html&quot; title=&quot;Acquisition des capitaux&quot;&gt;g&#233;n&#233;rer du capital&lt;/a&gt; et pour contraindre les autres &#224; l&#39;aider. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;demi-orque&lt;/a&gt; voit la port&#233;e de sa comp&#233;tence Intimidation augmenter de 9 m&#232;tres et la dur&#233;e du changement d&#39;attitude du &#224; une Intimidation r&#233;ussie doubler.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Lecture-Des-Pens&#233;es.html&quot; title=&quot;Lunettes de lecture des pens&#233;es&quot;&gt;Lunettes de lecture des pens&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Apr&#232;s 3 round d&#39;&#233;tude, permet de scanner les pens&#233;es de surface d&#39;une cr&#233;ature comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;D&#233;tection de pens&#233;es&quot;&gt;d&#233;tection de pens&#233;es&lt;/a&gt;&lt;/i&gt;. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Andro&#239;de-(Race).html&quot; title=&quot;Les andro&#239;des&quot;&gt;andro&#239;de&lt;/a&gt; peut d&#233;penser une utilisation d&#39;afflux de nanites pour scanner les pens&#233;es de surface d&#39;une cr&#233;ature imm&#233;diatement.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;sicles-De-D&#233;tection-Des-Chim&#232;res.html&quot; title=&quot;B&#233;sicles de d&#233;tection des chim&#232;res&quot;&gt;B&#233;sicles de d&#233;tection des chim&#232;res&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus de comp&#233;tence de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les illusions (chim&#232;re) et permettent de tenter un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; pour d&#233;voiler ces derni&#232;res sans interagir avec elles.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lentilles-De-T&#233;n&#232;bres.html&quot; title=&quot;Lentilles de t&#233;n&#232;bres&quot;&gt;Lentilles de t&#233;n&#232;bres&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Prot&#232;ge un porteur ayant la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Sensibilit&#233;-&#192;-La-Lumi&#232;re-(Capacit&#233;).html&quot; title=&quot;Sensibilit&#233; &#224; la lumi&#232;re (Ext)&quot;&gt;sensibilit&#233; &#224; la lumi&#232;re&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Aveugl&#233;-Par-La-Lumi&#232;re-(Capacit&#233;).html&quot; title=&quot;Aveugl&#233; par la lumi&#232;re (Ext)&quot;&gt;aveugl&#233; par la lumi&#232;re&lt;/a&gt; des effets du soleil, du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Du-Jour.html&quot; title=&quot;Lumi&#232;re du jour&quot;&gt;lumi&#232;re du jour&lt;/a&gt;&lt;/i&gt; et des effets similaires, en permanence.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Nyctalope.html&quot; title=&quot;Lunettes de nyctalope&quot;&gt;Lunettes de nyctalope&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#VISIONDANSLENOIR&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;vision dans le noir&lt;/a&gt; (18 m) en permanence.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-De-Laveugle.html&quot; title=&quot;Bandeau de l’aveugle&quot;&gt;bandeau de l’aveugle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les avantages du don &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-En-Aveugle.html&quot; title=&quot;Science du combat en aveugle&quot;&gt;Science du combat en aveugle&lt;/a&gt;. Occulte la vision du porteur.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monocle-Des-Auras-D&#233;voil&#233;es.html&quot; title=&quot;Monocle des auras d&#233;voil&#233;es&quot;&gt;Monocle des auras d&#233;voil&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de b&#233;n&#233;ficier des effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Chaos.html&quot; title=&quot;D&#233;tection du Chaos&quot;&gt;d&#233;tection du Chaos&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mal.html&quot; title=&quot;D&#233;tection du Mal&quot;&gt;du Mal&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Bien.html&quot; title=&quot;D&#233;tection du Bien&quot;&gt;du Bien&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;de la magie&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Loi.html&quot; title=&quot;D&#233;tection de la Loi&quot;&gt;de la Loi&lt;/a&gt;&lt;/i&gt; &#224; volont&#233; (mais une seule &#224; la fois). Conf&#232;re un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; pour passer les protections magiques (et ces tests utilisent le plus haut NLS entre celui du porteur et de l&#39;objet). Au prix d&#39;une utlisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Magique.html&quot; title=&quot;Vision magique&quot;&gt;vision magique&lt;/a&gt;&lt;/i&gt; et de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l&#39;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; pendant 1 heure.&lt;/td&gt;&lt;td&gt;12 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Vision-&#192;-360&#176;.html&quot; title=&quot;Lunettes de vision &#224; 360&#176;&quot;&gt;Lunettes de vision &#224; 360&#176;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-&#192;-360&#176;-(Capacit&#233;).html&quot; title=&quot;Vision &#224; 360&#176; (Ext)&quot;&gt;vision &#224; 360&#176;&lt;/a&gt; en permanence.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Du-Saboteur.html&quot; title=&quot;Lunettes du saboteur&quot;&gt;Lunettes du saboteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ordre-Assassin.html&quot; title=&quot;Ordre assassin&quot;&gt;ordre assassin&lt;/a&gt;&lt;/i&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Regard-(Capacit&#233;).html&quot; title=&quot;Regard (Sur)&quot;&gt;attaque de regard&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Dombreterre.html&quot; title=&quot;Lunettes d’Ombreterre&quot;&gt;lunettes d’ombreterre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#VISIONDANSLENOIR&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;vision dans le noir&lt;/a&gt; (36 m) et un bonus de comp&#233;tence de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; pour suivre des pistes dans des complexes souterrains.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Sniper.html&quot; title=&quot;Lunettes de sniper&quot;&gt;Lunettes de sniper&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur poss&#233;dant la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaque sournoise&lt;/a&gt; peut en effectuer &#224; n’importe quelle distance, il obtient un bonus de circonstance de +2 sur chaque d&#233; de d&#233;g&#226;ts de l’attaque sournoise s’il l’effectue &#224; 9 m ou moins de sa cible.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Sniper-Sup&#233;rieures.html&quot; title=&quot;Lunettes de sniper sup&#233;rieures&quot;&gt;Lunettes de sniper sup&#233;rieures&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionnent comme des &lt;i&gt;Lunettes de Sniper&lt;/i&gt;, mais le bonus de circonstance +2 aux d&#233;s de d&#233;g&#226;ts des attaques sournoises s’applique quelle que soit la distance.&lt;/td&gt;&lt;td&gt;| 50 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Masque-Des-Identit&#233;s-Vol&#233;es.html&quot; title=&quot;Masque des identit&#233;s vol&#233;es&quot;&gt;Masque des identit&#233;s vol&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut modifier l&#39;apparence du porteur pour correspondre &#224; celle d&#39;une cr&#233;ature touch&#233;e comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Modification-Dapparence.html&quot; title=&quot;Modification d&amp;#39;apparence&quot;&gt;modification d&#39;apparence&lt;/a&gt;&lt;/i&gt;, mais copiant l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;individu sp&#233;cifique&lt;/a&gt; touch&#233;. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Aquatique-(Race).html&quot; title=&quot;Les aquatiques&quot;&gt;aquatique&lt;/a&gt; peut obtenir une r&#233;ponse &#224; une question simple connue de la cr&#233;ature cibl&#233;e lorsqu&#39;il prend son apparence.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Arc-En-Ciel.html&quot; title=&quot;Lunettes arc-en-ciel&quot;&gt;Lunettes arc-en-ciel&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Couleurs-Dansantes.html&quot; title=&quot;Couleurs dansantes&quot;&gt;couleurs dansantes&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lueurs-Hypnotiques.html&quot; title=&quot;Lueurs hypnotiques&quot;&gt;lueurs hypnotiques&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lueur-Darc-En-Ciel.html&quot; title=&quot;Lueur d&amp;#39;arc-en-ciel&quot;&gt;lueur d’arc-en-ciel&lt;/a&gt;&lt;/i&gt;. Le porteur voit en nuances de gris.&lt;/td&gt;&lt;td&gt;21 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-Dannihilation.html&quot; title=&quot;Lunettes d&amp;#39;annihilation&quot;&gt;lunettes d’annihilation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#ECOLEDEMAGIE&quot; title=&quot;Le magicien&quot;&gt;transmutateur&lt;/a&gt; peut convertir n’importe quel sort de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;transmutation&lt;/a&gt; pr&#233;par&#233; en un autre sort de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;transmutation&lt;/a&gt; connu. Une fois par jour, il peut d&#233;penser un sort de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;transmutation&lt;/a&gt; de niveau 6 ou plus pour lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sint&#233;gration.html&quot; title=&quot;D&#233;sint&#233;gration&quot;&gt;d&#233;sint&#233;gration&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-Danath&#232;me.html&quot; title=&quot;Yeux d&amp;#39;anath&#232;me&quot;&gt;yeux d’anath&#232;me&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perception-De-La-Mort.html&quot; title=&quot;Perception de la mort&quot;&gt;perception de la mort&lt;/a&gt;&lt;/i&gt; en permanence. Chaque round, le porteur peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anath&#232;me.html&quot; title=&quot;Anath&#232;me&quot;&gt;anath&#232;me&lt;/a&gt;&lt;/i&gt; par une attaque de regard. Une fois par semaine, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terreur.html&quot; title=&quot;Terreur&quot;&gt;terreur&lt;/a&gt;&lt;/i&gt; par une attaque de regard.&lt;/td&gt;&lt;td&gt;25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;sicles-Du-Mauvais-Œil.html&quot; title=&quot;B&#233;sicles du mauvais œil&quot;&gt;B&#233;sicles du mauvais œil&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Onze &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par jour, permettent de lancer &lt;a class=&quot;pagelink&quot; href=&quot;Mauvais-Œil.html&quot; title=&quot;Mauvais œil&quot;&gt;mauvais œil&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; ne sont par forc&#233;ment cons&#233;cutifs et n’affectent qu’une cible par une.&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-De-Charme.html&quot; title=&quot;Yeux de charme&quot;&gt;Yeux de charme&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permettent de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Personne.html&quot; title=&quot;Charme-personne&quot;&gt;charme-personne&lt;/a&gt;&lt;/i&gt; sur une cible par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;56 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monocle-Dinvestigateur.html&quot; title=&quot;Monocle d’investigateur&quot;&gt;monocle d’investigateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, le porteur peut se concentrer sur une zone de 3 m&#232;tres de c&#244;t&#233; pendant 1 minutes ininterrompue pour observer ce qui s’y est pass&#233; les 24 derni&#232;res heures.&lt;/td&gt;&lt;td&gt;66 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cache-Œil-Du-Tyran-Des-Mers.html&quot; title=&quot;Cache-œil du tyran des mers&quot;&gt;Cache-œil du tyran des mers&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets des sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caresse-De-La-Mer.html&quot; title=&quot;Caresse de la mer&quot;&gt;caresse de la mer&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Respiration-Aquatique.html&quot; title=&quot;Respiration aquatique&quot;&gt;respiration aquatique&lt;/a&gt;&lt;/i&gt; en permanence. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Monstre-De-Groupe.html&quot; title=&quot;Charme-monstre de groupe&quot;&gt;charme-monstre de groupe&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;70 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bandeau-Du-Ma&#238;tre-Darmes.html&quot; title=&quot;Bandeau du ma&#238;tre d’armes&quot;&gt;bandeau du ma&#238;tre d’armes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rep&#233;rer-Les-Faiblesses.html&quot; title=&quot;Rep&#233;rer les faiblesses&quot;&gt;rep&#233;rer les faiblesses&lt;/a&gt;&lt;/i&gt; au corps &#224; corps en permanence et la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; (allonge de l’arme du porteur). Occulte la vision du porteur.&lt;/td&gt;&lt;td&gt;80 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-De-Domination-Mentale.html&quot; title=&quot;Yeux de domination mentale&quot;&gt;Yeux de domination mentale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Monstre.html&quot; title=&quot;Charme-monstre&quot;&gt;charme-monstre&lt;/a&gt;&lt;/i&gt; &#224; volont&#233; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domination.html&quot; title=&quot;Domination&quot;&gt;domination&lt;/a&gt;&lt;/i&gt; une fois par jour.&lt;/td&gt;&lt;td&gt;95 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Yeux-De-Dragon.html&quot; title=&quot;Yeux de dragon&quot;&gt;Yeux de dragon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent la &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#VISIONDANSLENOIR&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;vision dans le noir&lt;/a&gt; (36 m) et la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Aveugle-(Capacit&#233;).html&quot; title=&quot;Perception aveugle (Ext)&quot;&gt;perception aveugle&lt;/a&gt; (18 m) en permanence. Le porteur voit 4 fois plus loin dans les zones faiblement &#233;clair&#233;es et deux fois plus loin dans les zones normalement &#233;clair&#233;es.&lt;/td&gt;&lt;td&gt;110 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lunettes-De-Vision-Lucide.html&quot; title=&quot;Lunettes de vision lucide&quot;&gt;Lunettes de vision lucide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/i&gt; en permanence. Une fois par jour, permettent de lancer &lt;a class=&quot;pagelink&quot; href=&quot;Analyse-Denchantement.html&quot; title=&quot;Analyse d&amp;#39;enchantement&quot;&gt;analyse d’enchantement&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;184 800 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
